        }
    }

    private static File getSettingsFile(Context ctx) {
        return new File(String.format("%s/Andoop/%s/settings.xml", Environment.getExternalStorageDirectory(), ctx.getPackageName()));
    }

    private static JSONObject readJson(Context ctx) {
        File file = getSettingsFile(ctx);
        if (!file.exists()) {
            return EMPTY;
        }
        try {
            FileInputStream fin = new FileInputStream(file);
            byte[] buffer = new byte[fin.available()];
