            intent.setFlags(603979776);
            intent.setClassName(PACKAGE, CLASS_LISTSCORE);
            intent.putExtra("pkg_name", this.mPkgName);
            try {
                this.mContext.startActivity(intent);
                return;
            } catch (ActivityNotFoundException e) {
                Log.e(this.TAG, e.toString());
