    public void submitScore(int newScoreInt, String newScoreDisplay, String subBoard) {
        if (isInstalled()) {
            if (TextUtils.isEmpty(subBoard)) {
                subBoard = "";
            }
            Intent intent = new Intent();
            intent.setFlags(603979776);
            intent.setClassName(PACKAGE, CLASS_HIGHSCORE);
            intent.putExtra("pkg_name", this.mPkgName);
            intent.putExtra(HighScoreNames.SUBBOARD, subBoard);
            intent.putExtra(HighScoreNames.SCORE_INTEGER, newScoreInt);
