        if (this.mStatus != status && mGameView != null) {
            mGameView.reCycle();
            System.gc();
        }
        freeGameView();
        switch (status) {
            case 2:
                mGameView = new ScreenMenu(this.mContext, this);
                break;
            case 3:
                int step = 0;
                if (obj.length == 1) {
                    step = ((Integer) obj[0]).intValue();
                }
                mGameView = new ScreenIntro(this.mContext, step, this);
                break;
            case 4:
                mGameView = new ScreenHow(this.mContext, this);
                break;
            case 5:
                mGameView = new ScreenPlan(this.mContext, this);
                ScreenPlan sp = (ScreenPlan) mGameView;
                sp.setLevel(this.mLevel);
                break;
            case 6:
                mGameView = new ScreenLeft(this.mContext, this);
                break;
            case 7:
                if (mGameView == null) {
                    mGameView = new ScreenGame(this.mContext, this);
                }
                ScreenGame sg = (ScreenGame) mGameView;
                sg.setLevel(this.mLevel);
                break;
            case 8:
                mGameView = new ScreenOver(this.mContext, this);
                break;
            case Static.GAME_SUCCESS /* 9 */:
                mGameView = new ScreenSuccess(this.mContext, this);
                break;
        }
        setStatus(status);
    }

