    public void submitScore() {
        if (this.mLevel == 0 || this.mDays == 14) {
            controlView(2, new Object[0]);
            return;
        }
        StringBuilder sb = new StringBuilder();
        if (this.mLevel == 5) {
            sb.append("Congratulations! ");
        }
        sb.append(String.format("你得了 %s 分在 %s 天内, ", Integer.valueOf(this.mLevel), Integer.valueOf(14 - this.mDays)));
        long startTime = getLong("hs_start_time", 0L);
        long timeUsed = (System.currentTimeMillis() - startTime) / 1000;
        if (startTime > 0) {
            sb.append(String.format("准确的说是在 %s 秒之内, ", Long.valueOf(timeUsed)));
        }
        final int points = (int) ((((this.mLevel * 1000000) + (this.mDays * 10000)) + 10000) - timeUsed);
        sb.append(String.format("得了 %s 分！ ", Integer.valueOf(points)));
        sb.append("你想把你的分数上传到高分排行榜吗？");
        String message = sb.toString();
        DialogInterface.OnClickListener lsn1 = new DialogInterface.OnClickListener() { // from class: com.andoop.jailbreak.MainGame.1
            @Override // android.content.DialogInterface.OnClickListener
            public void onClick(DialogInterface dialog, int which) {
                String subboard = Static.getSubboard(MainGame.this.mContext);
                MainGame.this.mActivity.mScoreManager.submitScore(points, String.valueOf(points) + " points", subboard);
                MainGame.this.initGame();
            }
        };
        DialogInterface.OnClickListener lsn2 = new DialogInterface.OnClickListener() { // from class: com.andoop.jailbreak.MainGame.2
            @Override // android.content.DialogInterface.OnClickListener
            public void onClick(DialogInterface dialog, int which) {
                MainGame.this.initGame();
            }
        };
        this.mDialog = Constant.buildAlertInfo(this.mActivity, com.androidn.jailbreak.R.string.title_score, message, com.androidn.jailbreak.R.string.btn_submit, com.androidn.jailbreak.R.string.btn_exit, lsn1, lsn2, android.R.drawable.ic_dialog_info);
        this.mDialog.show();
    }

