    public void dealItem() {
        this.mMainGame.playMusic(com.androidn.jailbreak.R.raw.button_press, false);
        this.mMainGame.nextDay();
        if (this.mCop.isFound() || this.mClock.isOver()) {
            this.mMainGame.controlView(8, new Object[0]);
            return;
        }
        if (this.mMainGame.isSuccess()) {
            this.mMainGame.nextLevel();
            this.mMainGame.controlView(9, new Object[0]);
        } else if (this.mBar.isDone()) {
            this.mMainGame.nextLevel();
            this.mMainGame.controlView(5, new Object[0]);
        }
    }

package com.andoop.jailbreak;

    private void dealPause() {
        boolean isPaused = !this.mMainGame.getBoolean("pauseEnabled", false);
        this.mMainGame.putBoolean("pauseEnabled", isPaused);
        this.mMainGame.mActivity.mIsPaused = isPaused;
        if (isPaused) {
            doPause();
        } else {
            undoPause();
        }
    }

