    private void drawBar(Canvas canvas) {
        if (this.mCop.isFound()) {
            this.mBar.stop();
        } else {
            this.mBar.next();
            if (this.mBar.isDone() && !this.isDone) {
                this.isDone = true;
                this.mMainGame.playMusic(com.androidn.jailbreak.R.raw.task_success, false);
            }
        }
        this.mBar.onDraw(canvas);
    }

