    private void drawClock(Canvas canvas) {
        if (this.mClock.isOver()) {
            this.mMainGame.nextDay();
            this.mMainGame.controlView(8, new Object[0]);
        } else {
            if (!this.mBar.isDone()) {
                this.mClock.next();
            }
            this.mClock.onDraw(canvas);
        }
    }

package com.andoop.jailbreak;

    private void drawCop(Canvas canvas) {
        if (!this.mBar.isDone() || this.mCop.isFound()) {
            if (this.mCop.canCatch() && this.mBar.isGrowing() && this.mCop.catchRun()) {
                this.mMainGame.playMusic(com.androidn.jailbreak.R.raw.task_failed, false);
            }
            if (!this.mMainGame.mActivity.mIsPaused) {
                this.mCop.move();
            }
            this.mCop.onDraw(canvas);
        }
    }

