    private void drawHero(Canvas canvas) {
        if (this.frames % 2 == 0 && !this.mMainGame.mActivity.mIsPaused) {
            this.mHero.nextFrame();
        }
        if (this.mBar.isDone()) {
            this.mHero.setImage(this.mHeroIdle, this.pHeroIdle[2], this.pHeroIdle[3]);
            this.mHero.setFrame(0);
        }
        if (this.mCop.isFound()) {
            this.mHero.setImage(this.mHeroWork, this.pHeroWork[this.mLevel][2], this.pHeroWork[this.mLevel][3]);
            this.mHero.setFrame(0);
        }
        this.mHero.paint(canvas);
    }

