    protected void onDraw(Canvas canvas) {
        this.frames++;
        Static.drawImage(canvas, this.mWall, 0.0f, 0.0f);
        drawCop(canvas);
        Static.drawImage(canvas, this.mBackground, 0.0f, 0.0f);
        drawHero(canvas);
        drawBar(canvas);
        this.mCalendar.onDraw(canvas);
        drawTool(canvas);
        drawDone(canvas);
        drawButton(canvas);
        drawAlert(canvas);
        drawClock(canvas);
        this.mBtnPause.paint(canvas);
    }

