    public boolean onKeyDown(int keyCode, KeyEvent event) {
        if (keyCode == 4) {
            if (this.mBar.isDone()) {
                return true;
            }
            this.mMainGame.stopMusic();
            this.mClock.stop();
            this.mMainGame.submitScore();
        }
        return true;
    }

package com.andoop.jailbreak;

    public boolean onTouchEvent(MotionEvent event) {
        int x = (int) event.getRawX();
        int y = (int) event.getRawY();
        if (isFoundDone()) {
            handleTouchEvent(event, this.mBtnNext);
            return true;
        }
        int action = event.getAction();
        if (action == 0 && this.mBtnPause.containsPoint(x, y)) {
            dealPause();
            return true;
        }
        if (!this.mBtnPause.containsPoint(x, y, (this.W * 27) / Static.SCREENH) && !this.mMainGame.mActivity.mIsPaused) {
            switch (action) {
                case 1:
                    if (!isFoundDone()) {
                        heroWait();
                        break;
                    }
                    break;
                default:
                    if (!this.mBar.isDone()) {
                        heroWork();
                        break;
                    }
                    break;
            }
            return true;
        }
        return true;
    }

