        this.mMainGame.putFloat("mCopX", this.mCopX);
        this.mMainGame.putFloat("mCopY", this.mCopY);
        this.mMainGame.putInt("mStatus", this.mStatus);
        this.mMainGame.putInt("mShows", this.mShows);
        this.mMainGame.putInt("mCurrent", this.mCurrent);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < this.mSeq.length; i++) {
            sb.append(this.mSeq[i]);
            sb.append(",");
        }
