        }
        this.mStatus = 4;
        this.mSeq = new int[]{4};
        this.mFoundTime = 30;
        return true;
    }

    public boolean isOver() {
        return this.mIsOver && getPValue() != 1;
    }

    public boolean isFound() {
        return this.mStatus == 4;
    }

    public boolean canCatch() {
        return getPValue() != 1 && ((double) this.mCopX) < ((double) this.W) - (((double) this.mCopW) * 1.4d) && (this.mStatus == 2 || this.mStatus == 3);
    }
