        SharedPreferences settings = this.context.getSharedPreferences("mobclix_" + this.applicationId, 0);
        int notifyUserResponse = settings.getInt("analytics_enabled", -1);
        this.isMobclixEnabledKnown = notifyUserResponse != -1;
        if (this.isMobclixEnabledKnown) {
            if (notifyUserResponse == 0) {
                this.isMobclixEnabled = DEBUG;
                return;
            } else {
                if (notifyUserResponse == 1) {
                    this.isMobclixEnabled = true;
                    return;
