        new AlertDialog.Builder(this.context).setCancelable(DEBUG).setTitle(appName).setMessage("This application would like to gather anonymous usage statistics.").setNegativeButton("Don't Allow", new DialogInterface.OnClickListener() { // from class: com.mobclix.android.sdk.Mobclix.1
            @Override // android.content.DialogInterface.OnClickListener
            public void onClick(DialogInterface dialog, int whichButton) {
