    private void initialize(Context context, String applicationId, int logLevelSetting, boolean notifyUserSetting) {
        this.context = context;
        this.applicationId = applicationId;
        this.androidVersion = Build.VERSION.RELEASE;
        this.deviceId = Settings.System.getString(context.getContentResolver(), "android_id");
        if (this.deviceId == null) {
            this.deviceId = "Emulator";
        }
        this.deviceType = String.valueOf(Build.DEVICE) + "-" + Build.MODEL + "-" + Build.PRODUCT;
        this.logLevel = logLevelSetting;
        String app_name = context.getPackageName();
        PackageManager package_manager = context.getPackageManager();
        try {
            this.applicationVersion = package_manager.getPackageInfo(app_name, 0).versionName;
        } catch (PackageManager.NameNotFoundException e) {
            this.applicationVersion = "null";
        }
        this.longitude = "null";
        this.latitude = "null";
        this.haveLocationPermission = DEBUG;
        if (package_manager.checkPermission("android.permission.ACCESS_FINE_LOCATION", app_name) == 0) {
            this.locationCriteria = new Criteria();
            this.locationCriteria.setAccuracy(1);
            this.haveLocationPermission = true;
        } else if (package_manager.checkPermission("android.permission.ACCESS_COARSE_LOCATION", app_name) == 0) {
            this.locationCriteria = new Criteria();
            this.locationCriteria.setAccuracy(2);
            this.haveLocationPermission = true;
        } else {
            this.haveLocationPermission = DEBUG;
        }
        if (package_manager.checkPermission("android.permission.ACCESS_NETWORK_STATE", app_name) == 0) {
            this.haveNetworkStatePermission = true;
        } else {
            this.haveNetworkStatePermission = DEBUG;
        }
        if (this.haveLocationPermission) {
            this.locationCriteria.setCostAllowed(DEBUG);
            this.locationCriteria.setBearingRequired(DEBUG);
            this.locationCriteria.setAltitudeRequired(DEBUG);
            this.locationCriteria.setSpeedRequired(DEBUG);
        }
        TelephonyManager telephoney_manager = (TelephonyManager) context.getSystemService("phone");
        this.locale = telephoney_manager.getSimCountryIso();
        if (this.locale == null) {
            this.locale = "null";
        }
    }

